//autogenerated:yes
//nolint:revive,govet,errcheck
package common_test

import (
	"testing"

	dialectpkg "github.com/bluenviron/gomavlib/v4/pkg/dialects/common"
	"github.com/stretchr/testify/require"
)

func TestEnum_GRIPPER_ACTIONS(t *testing.T) {
	t.Run("zero", func(t *testing.T) {
		var e dialectpkg.GRIPPER_ACTIONS
		e.UnmarshalText([]byte{})
		e.MarshalText()
		e.String()
	})

	t.Run("first entry", func(t *testing.T) {
		enc, err := dialectpkg.GRIPPER_ACTION_RELEASE.MarshalText()
		require.NoError(t, err)

		var dec dialectpkg.GRIPPER_ACTIONS
		err = dec.UnmarshalText(enc)
		require.NoError(t, err)

		require.Equal(t, dialectpkg.GRIPPER_ACTION_RELEASE, dec)
	})
}
